/* INFO6007 — quiz bank.
 * Entry shape: { ch, type: "study"|"math", q, opts: [..], answer: <index>, exp }
 * type "study" = answerable from chapterN-study.html
 * type "math"  = answerable from chapterN-math.html (quantitative foundations)
 */
var ALL_QUIZ_DATA = [

  /* Ch1 */
  { ch: 1, type: "study", q: "A team is asked to migrate 400 mailboxes to a new tenant by 30 June. Which feature makes this a project rather than an operation?", opts: ["It is temporary and produces a unique result","It is technically complex and needs specialists","It costs more than the department's annual run budget","It is performed by a permanent functional team"], answer: 0, exp: "A project is temporary — a defined start and end — and creates a unique product, service or result. Complexity, cost and team size are not the tests: the nightly identity reconciliation in the same list is complex, expensive and ongoing, so it is an operation." },
  { ch: 1, type: "study", q: "A cloud migration, an identity refresh, a CRM replacement and a data platform share one identity-service dependency and are managed together to realise benefits none could deliver alone. What is this?", opts: ["A portfolio, because it groups work by strategic investment","A program, because related projects are coordinated for combined benefits","A single project, because the four components share a dependency","An operation, because the work continues release after release"], answer: 1, exp: "Coordinating related projects to obtain benefits not available from managing them separately is program management. A portfolio groups programs and projects for investment and prioritisation decisions; a shared dependency does not merge four projects into one; and ongoing repetitive work is an operation." },
  { ch: 1, type: "study", q: "A sponsor cuts the project budget by 15% and insists that scope, the delivery date and the quality standard are all unchanged. On the Week 1 constraint system, what has actually happened?", opts: ["Scope must automatically fall by the same 15%","The schedule shortens, because less money buys less work","The saving has been paid for out of quality and risk, whether or not anyone records it","Nothing else changes, because cost is independent of scope, time and quality"], answer: 2, exp: "The constraints are interdependent and quality and risk sit inside the triangle, so a cost cut that is not matched by a scope or time change must be absorbed by quality and risk. That is the third rule candidates forget, and it is what the Aurora Tech CRM case demonstrates." },
  { ch: 1, type: "study", q: "Where do the risk register and the lessons-learned record first belong in the five-stage lifecycle?", opts: ["Both in monitoring and controlling","The risk register in initiating; lessons learned in executing","Both in executing, because that is where the work happens","The risk register in planning; lessons learned in closing"], answer: 3, exp: "Planning produces the scope, schedule, cost and quality baselines plus the risk register; closing produces final acceptance, transition and lessons learned. Monitoring and controlling runs in parallel with executing rather than replacing those artefacts." },
  { ch: 1, type: "study", q: "The Aurora Tech CRM was delivered four months late and 40% over its $500,000 budget, and staff barely used it. Which statement best explains why trust in IT fell?", opts: ["Adoption and business value are success dimensions, so the project failed on value as well as on delivery","Lateness alone destroys trust, whatever the product does","The project failed only because the original budget was too small","Cost and schedule overruns are unavoidable in IT, so no conclusion follows"], answer: 0, exp: "Success is measured across dimensions including adoption, business value, stakeholder satisfaction and long-term operational impact. Aurora scored acceptably on delivery but negatively on adoption and value, and only that third fact explains the loss of trust." },
  { ch: 1, type: "study", q: "A project's sponsor never attends steering meetings and nobody can say who approves a change request. Which failure pattern is this, and which response fits it?", opts: ["Optimism bias in estimation; respond with three-point estimating","Weak governance and unclear decision rights; respond with a charter, a governance structure and an escalation path","Underestimated integration complexity; respond with a dependency map","Volatile requirements; respond with a WBS and change control"], answer: 1, exp: "An absent sponsor and undefined decision rights are a governance failure, answered by the charter, a governance structure and an escalation path. Estimation bias, integration complexity and volatile requirements are different patterns with different responses, and none of them produces this symptom." },
  { ch: 1, type: "math", q: "A network has A (4 days), then B (6 days) and C (3 days) running in parallel, then D (7 days) which needs both B and C, then E (2 days). What is the project duration, and how much float does C have?", opts: ["16 days, and C is on the critical path with zero float","19 days, and C has 7 days of float","19 days, and C has 3 days of float","22 days, and C has 3 days of float"], answer: 2, exp: "Path A-B-D-E = 4 + 6 + 7 + 2 = 19 days and path A-C-D-E = 4 + 3 + 7 + 2 = 16 days, so the duration is 19 days and C's branch carries 19 − 16 = 3 days of float. C finishes on day 7 while B finishes on day 10, and D waits for B." },
  { ch: 1, type: "math", q: "A CRM project has BAC $120,000. At the end of month 3 the plan says 62.5% should be complete, only 50% is complete, and $75,000 has been spent. What are CV and CPI?", opts: ["CV = +$15,000 and CPI = 1.25","CV = −$15,000 and CPI = 0.94","CV = −$25,000 and CPI = 0.80","CV = −$15,000 and CPI = 0.80"], answer: 3, exp: "EV = 0.50 × 120,000 = $60,000, PV = 0.625 × 120,000 = $75,000, so CV = EV − AC = 60,000 − 75,000 = −$15,000 and CPI = EV/AC = 60,000/75,000 = 0.80. The 0.94 distractor divides EV by PV, which is SPI, and +$15,000 reverses the sign convention." },
  { ch: 1, type: "math", q: "A project spends $24,000 on prevention and $30,000 on appraisal, and incurs $26,000 of internal failure and $70,000 of external failure. What is the cost of non-conformance, and what share of the total cost of quality is it?", opts: ["$96,000 — 64% of the $150,000 total","$54,000 — 36% of the $150,000 total","$96,000 — 36% of the $150,000 total","$70,000 — 47% of the $150,000 total"], answer: 0, exp: "Non-conformance = internal failure + external failure = 26,000 + 70,000 = $96,000; conformance = 24,000 + 30,000 = $54,000; CoQ = $150,000 and 96,000/150,000 = 64%. The $54,000 figure is the conformance half, and $70,000 is only the external-failure component." },
  { ch: 1, type: "math", q: "A WBS of seven work packages totals 1,640 hours of effort at a blended rate of $85 per hour, delivered by five people each available 7 productive hours a day. What are the labour cost and the aggregated duration?", opts: ["$139,400 and about 9 working days","$139,400 and about 47 working days","$164,000 and about 47 working days","$139,400 and about 235 working days"], answer: 1, exp: "Labour cost = 85 × 1,640 = $139,400, and duration = 1,640 / (5 × 7) = 46.9 ≈ 47 working days, about 9.4 working weeks. Dividing by 7 instead of 35 produces the 235-day distractor, and $164,000 applies a $100 rate." },

  /* Ch2 */
  { ch: 2, type: "study", q: "A project manager has just been appointed to a new e-commerce platform, but no charter exists. What does the charter actually provide?", opts: ["The detailed schedule, cost baseline and risk register for the delivery phase","The vendor evaluation criteria and the contract type to be used","Formal authorisation for the project and the manager's authority to use organisational resources","The change control procedure the team must follow once delivery starts"], answer: 2, exp: "The charter authorises the project and grants the project manager authority over organisational resources; it establishes the vision, aligns stakeholders and gives a high-level road map. The baselines and registers are planning outputs, and vendor material belongs to procurement." },
  { ch: 2, type: "study", q: "A government compliance system has stable, fully documented requirements, fixed-price stage-gate approvals and a contractual documentation deliverable. Which methodology fits, and why?", opts: ["Scrum, because sprints would absorb any late requirement changes","Kanban, because WIP limits would shorten the approval queue","DevOps, because CI/CD shortens the release cycle","Waterfall, because the requirements are stable and the gate documentation is itself a deliverable"], answer: 3, exp: "Waterfall is sequential and suits fixed scope, clear milestones and documentation-heavy compliance or government work. Sprint-based and flow-based methods earn their cost when requirements evolve, and CI/CD addresses release speed rather than the fixed-scope, gate-driven problem here." },
  { ch: 2, type: "study", q: "In Scrum, who owns the Product Backlog and decides its order?", opts: ["The Product Owner, because prioritisation is a value decision","The Scrum Master, because they remove blockers and protect the sprint","The development team, because they estimate the work","The sponsor, because they fund the project"], answer: 0, exp: "The Product Owner defines the features and manages and prioritises the Product Backlog. The Scrum Master coaches and facilitates, the team delivers the Increment and owns the Sprint Backlog, and the sponsor sits outside the Scrum roles." },
  { ch: 2, type: "study", q: "A hospital's written procedure manual describes a clean admissions process, but staff describe something quite different in interviews. Which technique best exposes the real process?", opts: ["A survey, because it reaches many staff quickly","Observation, because people describe the official process rather than the real one","Document analysis, because the manual is the authoritative record","A workshop, because conflicting views are resolved in the room"], answer: 1, exp: "Observation watches users interact with the current system and reveals the workarounds — the sticky note, the bypassing phone call — that documentation and self-reports hide. Surveys, documents and workshops each have a best-fit situation, but only observation sees the actual process." },
  { ch: 2, type: "study", q: "A regulator has high power over the project but very little interest in day-to-day progress. Where does it sit on the Power/Interest Grid, and what follows?", opts: ["Manage closely: engage daily and co-design the solution","Keep informed: send regular detailed updates","Keep satisfied: report enough that it never becomes an active blocker","Monitor: minimal effort, since interest is low"], answer: 2, exp: "High power with low interest maps to keep satisfied. Manage closely is for high power and high interest, keep informed for low power and high interest, and monitor for low power and low interest — and both axes are estimates that change as the project proceeds." },
  { ch: 2, type: "study", q: "Which delivery arrangement is a genuine hybrid rather than agile or predictive in disguise?", opts: ["A predictive plan executed strictly phase by phase with no iteration","Pure Scrum with no charter, no business case and no governance gates","Kanban with WIP limits applied to a fixed-price contract's milestones","A predictive charter, business case and stage gates, with agile increments delivering the scope inside them"], answer: 3, exp: "A hybrid keeps the predictive frame — charter, business case, governance gates and cost baseline — and runs delivery inside it in increments with a prioritised backlog. Removing the frame is not hybrid, and neither is executing phases sequentially." },
  { ch: 2, type: "math", q: "A support team completes 10 tickets a day and currently has 30 items in progress. A WIP limit of 20 is introduced and throughput holds. What happens to average cycle time?", opts: ["It falls from 3 days to 2 days","It falls from 3 days to 1.5 days","It rises from 0.33 days to 0.5 days","It is unchanged, because throughput did not change"], answer: 0, exp: "Little's Law gives CT = WIP / TH: 30/10 = 3 days before the limit and 20/10 = 2 days after it. The 1.5-day distractor wrongly divides the old WIP by the new limit, and inverting the ratio gives the 0.33 figure." },
  { ch: 2, type: "math", q: "At week 6 of a 12-week project, BAC is $180,000, PV is $90,000, EV is $81,000 and AC is $99,000. Which pair of indices is correct?", opts: ["CPI = 0.90 and SPI ≈ 0.82","CPI ≈ 0.82 and SPI = 0.90","CPI ≈ 1.22 and SPI = 0.90","CPI ≈ 0.82 and SPI ≈ 1.11"], answer: 1, exp: "CPI = EV/AC = 81,000/99,000 = 0.818 and SPI = EV/PV = 81,000/90,000 = 0.90. Swapping the two ratios gives the 0.90/0.82 pair, and 1.22 is the TCPI, (BAC − EV)/(BAC − AC), which is a different measure altogether." },
  { ch: 2, type: "math", q: "A weighted scorecard uses weights 0.20 for stability, 0.15 for evidence and gates, 0.25 for speed to first release, 0.25 for tolerance of change and 0.15 for predictable reporting. A hybrid method scores 4, 5, 4, 5 and 5 out of 5. What is its weighted total?", opts: ["4.35","5.00","4.55","4.15"], answer: 2, exp: "S = 0.20(4) + 0.15(5) + 0.25(4) + 0.25(5) + 0.15(5) = 0.80 + 0.75 + 1.00 + 1.25 + 0.75 = 4.55. Dropping one term gives 4.35 or 4.15, and 5.00 would require full marks on every criterion." },
  { ch: 2, type: "math", q: "A big-bang release carries a 20% chance of a $120,000 failure. A staged release carries a 10% chance of a $60,000 failure but costs $12,000 in extra overhead. On expected monetary value alone, which is better and by how much?", opts: ["Big-bang, by $6,000 (an EMV of −$18,000 against −$24,000)","Staged, by $18,000","They are equal, because both are negative","Staged, by $6,000 (an EMV of −$18,000 against −$24,000)"], answer: 3, exp: "Big-bang EMV = 0.20 × (−120,000) = −$24,000. Staged EMV = 0.10 × (−60,000) − 12,000 = −$18,000. Staging is better by $6,000, and the comparison only holds while its overhead stays below 24,000 − 6,000 = $18,000." },

  /* Ch3 */
  { ch: 3, type: "study", q: "Which schedule process produces the network diagram and the dependency list?", opts: ["Sequence activities","Define activities","Develop schedule","Estimate activity durations"], answer: 0, exp: "Sequencing takes the activity list that already exists and orders it logically, emitting the network diagram and the dependency list. Defining activities produces the activity list and attributes, estimating durations produces duration estimates with a basis, and developing the schedule produces the baseline, the Gantt chart and the critical path." },
  { ch: 3, type: "study", q: "Two activities could technically run in parallel, but the team's standard practice is to finish the security review before usability testing starts. What kind of dependency is this, and what follows for compression?", opts: ["Mandatory (hard logic), so it can never be compressed","Discretionary (soft logic), so it is the first place fast tracking looks","External, so it must be managed by contract and a fallback plan","Start-to-finish, so the successor's finish is tied to the predecessor's start"], answer: 1, exp: "Soft logic is chosen from best practice, preference or convenience and can be re-decided when the schedule demands it, which is exactly why fast tracking looks there first. Mandatory logic is inherent in the work, and an external dependency sits outside the team's control." },
  { ch: 3, type: "study", q: "A project must be shortened and no additional money is available. Which compression technique fits, and what does it cost?", opts: ["Crashing, which buys resources, shortens the critical path and adds no risk","Resource levelling, which moves work off the peak and shortens the end date","Fast tracking, which overlaps sequential work without buying resources but raises rework and interface risk","Reducing the float recorded on the near-critical activities"], answer: 2, exp: "Fast tracking performs originally sequential activities in parallel: no new money, but more rework, interface defects and coordination overhead. Crashing adds resources and therefore cost directly, levelling deliberately protects the end date rather than shortening it, and float cannot be reduced by decision." },
  { ch: 3, type: "study", q: "Which of these is a valid work package?", opts: ["Development phase","Transport for NSW","Licence-data integration","Interface tested against the TfNSW sandbox"], answer: 3, exp: "A work package is the lowest level you estimate, assign and control: one owner and a testable output. A phase is a summary level containing many deliverables, an organisation name is not a deliverable, and Licence-data integration is a deliverable that still has to be decomposed." },
  { ch: 3, type: "study", q: "In the enrolment project, training may start two days before end-to-end testing finishes, and the payment vendor's system access is only available from week 4. Which pair of timing modifiers is this?", opts: ["A lead for training and a lag for the vendor access","A lag for training and a lead for the vendor access","Both are lags, because both change a start date","Both are leads, because both overlap two activities"], answer: 0, exp: "A lead lets a successor start before its predecessor finishes, which accelerates the schedule; a lag makes the successor wait, which slows it. Reversing the two reverses the schedule effect, which is the classic Week 3 error." },
  { ch: 3, type: "math", q: "In the lecture network, activity G lasts 6 days, its predecessor D finishes on day 15, and its successors are H (LS 23) and I (LS 22). What is G's total float?", opts: ["5 days, because H starts later than I","1 day, because I and not H constrains G","0 days, because G feeds two successors","7 days, because G may start on day 16"], answer: 1, exp: "The backward pass takes the minimum late start among successors: LF_G = min(23, 22) = 22, so LS_G = 22 − 6 = 16 and float = LS − ES = 16 − 15 = 1 day. G starts on the same day as E but takes 6 days where E takes 7, so the longer branch wins and G is near-critical rather than critical." },
  { ch: 3, type: "math", q: "A vendor integration is estimated at O = 3, M = 6 and P = 15 weeks. What are the PERT expected duration and the standard deviation?", opts: ["E = 8 weeks and σ = 2.0 weeks","E = 7 weeks and σ = 0.5 weeks","E = 7 weeks and σ = 2.0 weeks","E = 7 weeks and σ = 12 weeks"], answer: 2, exp: "E = (3 + 4×6 + 15)/6 = 42/6 = 7.0 weeks — a weighted average, not the plain mean of 8.0 — and σ = (P − O)/6 = (15 − 3)/6 = 2.0 weeks. The 0.5 distractor divides by 24, and 12 is simply P − O." },
  { ch: 3, type: "math", q: "Two independent activities on the critical path have standard deviations of 2.33 and 1.67 weeks. What is the standard deviation of the path?", opts: ["4.00 weeks, because the deviations add","About 8.22 weeks, because the variances add","About 0.66 weeks, because the deviations partly cancel","About 2.87 weeks, because the variances add"], answer: 3, exp: "σ_path² = Σσ_i² = 2.33² + 1.67² = 5.43 + 2.79 = 8.22, so σ_path = √8.22 ≈ 2.87 weeks. Standard deviations are never added directly, and 8.22 is the variance rather than the deviation." },
  { ch: 3, type: "math", q: "An activity has ES = 9, EF = 14, LS = 10 and LF = 15. What is its float and what does it imply?", opts: ["1 day, so it is near-critical and must be watched in status reports","5 days, so it has comfortable float","0 days, so it defines the critical path","6 days, which is the gap between LF and ES"], answer: 0, exp: "Float = LS − ES = 10 − 9 = 1 day, confirmed by LF − EF = 15 − 14 = 1 day. Zero float defines a critical activity, and a small positive float defines a near-critical one: one day of slip here makes it critical." },
  { ch: 3, type: "math", q: "A (5 days) precedes both B (7 days) and C (6 days); C may not start before the vendor grants access on day 4; D (4 days) needs both B and C. How much float does C have?", opts: ["0 days","1 day","3 days","6 days"], answer: 1, exp: "A runs 0–5, B runs 5–12, and C starts at max(EF_A, 4) = 5 and runs 5–11. D starts at max(12, 11) = 12, so C's late finish is 12 and its float is 12 − 11 = 1 day. The one-day gap between B and C is exactly the float C carries, and it disappears if the vendor slips past day 5." },

  /* Ch4 */
  { ch: 4, type: "study", q: "Which cost elements sit inside the cost baseline?", opts: ["Direct costs only, because indirect costs are organisational overhead","Direct costs, indirect costs, contingency and management reserves","Direct costs, indirect costs and the contingency reserve","The cost estimates alone, before any reserve is added"], answer: 2, exp: "The cost baseline is the approved, time-phased budget, and it includes direct costs, indirect costs and contingency reserves. The management reserve sits outside the baseline but inside the total project budget." },
  { ch: 4, type: "study", q: "A worldwide hardware price rise hits the project and nobody identified it during risk planning. Which reserve answers it?", opts: ["The contingency reserve, because it is a cost risk and the baseline already holds it","The sunk-cost pool, because the money has already been committed","No reserve at all: the change must be absorbed by descoping","The management reserve, because it covers unpredictable situations outside the baseline"], answer: 3, exp: "The test is whether the risk was identified and sized in advance. Contingency answers identified, partially planned risks inside the baseline; an unidentified global price rise is what the management reserve exists for, and releasing it is a management decision. Sunk costs are excluded from the plan altogether." },
  { ch: 4, type: "study", q: "The team has already spent $80,000 on a prototype the project has now abandoned. How should that figure be treated?", opts: ["It is a sunk cost and is not included in the project management plan","It belongs in the cost baseline as a direct cost","It is drawn from the contingency reserve","It is added to the estimate at completion as committed cost"], answer: 0, exp: "Sunk cost is money already spent when deciding what to invest in, it can never be recovered, and it is excluded from the project management plan. It is not a baseline item, not a reserve draw, and committed cost (purchase orders raised) is not the same as actual cost." },
  { ch: 4, type: "study", q: "An EAC is required on the assumption that the earlier cost variance was a one-off and the remaining work follows the original plan. Which formula fits?", opts: ["EAC = BAC ÷ CPI","EAC = AC + (BAC − EV)","EAC = AC + (BAC − EV) ÷ (CPI × SPI)","EAC = BAC − ETC"], answer: 1, exp: "Adding the remaining budget to actual cost prices the rest of the work exactly as the baseline said. BAC/CPI assumes current cost performance continues, and AC + (BAC − EV)/(CPI × SPI) assumes both the cost and the schedule inefficiency persist — on the lecture's data those three answers differ by more than $55,000, which is why the assumption must be stated." },
  { ch: 4, type: "study", q: "Why is Planned Value unstable in an agile project?", opts: ["Velocity varies from sprint to sprint","Story points are not measured in dollars","The backlog is reprioritised, so the scope baseline that PV is calculated from keeps moving","Agile projects have no approved budget"], answer: 2, exp: "PV is derived from the scope baseline, and agile reprioritisation keeps changing what that baseline contains. Variable velocity and non-monetary story points are genuine difficulties, but the reason PV itself is unstable is the moving scope baseline." },
  { ch: 4, type: "math", q: "A six-month portal has BAC $180,000. At the end of month 3, PV is $85,000, EV is $80,000 and AC is $85,000. If the current CPI continues, what are EAC and VAC?", opts: ["EAC $191,250 and VAC +$11,250","EAC $180,000 and VAC $0","EAC $210,375 and VAC −$30,375","EAC $191,250 and VAC −$11,250"], answer: 3, exp: "CPI = EV/AC = 80,000/85,000 = 0.9412, so EAC = BAC/CPI = 180,000/0.9412 = $191,250 and VAC = BAC − EAC = −$11,250, an overrun. The $210,375 figure divides the $198,000 baseline-with-contingency by the same CPI — a defensible alternative reading, but not the BAC-based answer — and a positive VAC would wrongly report an underspend." },
  { ch: 4, type: "math", q: "Estimates total $250,000, contingency is set at 8% and management reserve at 4%. What are the cost baseline and the total project budget?", opts: ["Baseline $270,000; total budget $280,000","Baseline $270,000; total budget $270,000","Baseline $250,000; total budget $270,000","Baseline $280,000; total budget $300,000"], answer: 0, exp: "Contingency = 0.08 × 250,000 = $20,000, so the baseline = 250,000 + 20,000 = $270,000. Management reserve = 0.04 × 250,000 = $10,000, so the total budget = 270,000 + 10,000 = $280,000. The management reserve sits on top of the baseline, never inside it." },
  { ch: 4, type: "math", q: "PV is $150,000, EV is $130,000, AC is $120,000 and BAC is $520,000. Both the cost and the schedule performance are expected to persist. Which EAC applies, and what is it?", opts: ["$480,000, using BAC ÷ CPI","$535,385, using AC + (BAC − EV) ÷ (CPI × SPI)","$510,000, using AC + (BAC − EV)","$520,000, the original budget"], answer: 1, exp: "CPI = 130,000/120,000 = 1.0833 and SPI = 130,000/150,000 = 0.8667, so EAC = 120,000 + 390,000/(1.0833 × 0.8667) = $535,385. The $480,000 figure assumes only the cost performance persists, $510,000 assumes the deviation was a one-off, and the original budget is not a forecast." },
  { ch: 4, type: "math", q: "Cloud infrastructure is estimated at O = $8,000, M = $12,000 and P = $20,000. What is the three-point estimate?", opts: ["$13,333","$12,000","$12,667","$20,000"], answer: 2, exp: "(8,000 + 4 × 12,000 + 20,000)/6 = 76,000/6 = $12,666.67 ≈ $12,667. The plain arithmetic mean is $13,333, M alone is $12,000, and $20,000 is the pessimistic value." },
  { ch: 4, type: "math", q: "Development on the critical path slips by two weeks. Six people work on that path, 40 hours a week, at $60 an hour. What is the extra direct labour cost?", opts: ["$14,400","$7,200","$57,600","$28,800"], answer: 3, exp: "2 weeks × 6 people × 40 hours × $60 = $28,800 before any re-planning or penalty. $14,400 assumes three people and $7,200 assumes one." },

  /* Ch5 */
  { ch: 5, type: "study", q: "A team runs a sprint retrospective and changes how user stories are written, so that fewer ambiguous requirements reach development. Which quality process is this?", opts: ["Managing quality (assurance), because a process is being improved to prevent defects","Controlling quality, because the retrospective happened after the sprint finished","Planning quality management, because the story template is part of the plan","Cost of non-conformance, because it follows a defect"], answer: 0, exp: "Assurance is process-focused and preventive: audits, reviews, retrospectives and prevention activity change the way work is done before defects exist. Control is product-focused and detective, and planning produces the plan in the first place — the timing of the retrospective does not make it control." },
  { ch: 5, type: "study", q: "A licence app passes every technical specification test, but a police officer cannot verify a licence with it at the roadside. Which distinction has failed?", opts: ["Verification: the technical specification was not met","Validation: verification asks whether we built it right, validation whether we built the right thing","Neither, because passing verification means the product has quality","Cost of conformance, because too little was spent on appraisal"], answer: 1, exp: "Verification confirms the deliverable meets its specification; validation confirms it meets the user's need. A deliverable can pass every verification test and still fail validation, and that gap is where most external-failure cost lives." },
  { ch: 5, type: "study", q: "A release ships with a defect that miscalculates overtime pay. Payroll staff work a weekend to correct 1,200 payslips manually and the client raises a formal complaint. How are these costs classified?", opts: ["Appraisal, because the payslips had to be checked","Internal failure, because the defect was eventually fixed in house","External failure, which is part of the cost of non-conformance","Prevention, because the fix stops the defect recurring"], answer: 2, exp: "External failure is cost incurred after release, when the customer finds the defect: incidents, hotfixes, downtime, complaints and compensation. Internal failure happens before release, appraisal is testing and inspection spent to find defects, and prevention is spent before defects exist." },
  { ch: 5, type: "study", q: "An organisation holds ISO 9001 certification and has reached CMMI level 3, yet it ships a defective release. Is that contradictory?", opts: ["Yes: certification guarantees that released products conform to requirements","No: because CMMI applies only to hardware projects","Yes: ISO 9001 requires zero defects at release","No: standards and maturity models describe the capability of the process, not the quality of a particular product"], answer: 3, exp: "ISO 9001 certifies a quality management system and CMMI rates software process maturity, so both describe how work is done; a certified organisation can still ship a defect. Only measurable acceptance criteria and control activity tell you whether this release is fit to ship." },
  { ch: 5, type: "study", q: "Which of these is a usable acceptance criterion for quality control?", opts: ["95th-percentile response time ≤ 2 s at 5,000 concurrent users on the production-sized data set","The system should be responsive and easy to use","Performance testing will be carried out before release","Response time ≤ 2 s"], answer: 0, exp: "A criterion is only testable when it states the metric, the comparator, the threshold and the conditions (load and data set). The bare response-time target omits the load clause that made the enrolment-system launch fail, and the other two options state an aspiration and an activity rather than a measurable assertion." },
  { ch: 5, type: "math", q: "A project's quality spend is: prevention $30,000, appraisal $50,000, internal failure $70,000 and external failure $50,000. What is the total cost of quality, and what share is failure work?", opts: ["$200,000, of which 40% is non-conformance","$200,000, of which 60% is non-conformance","$120,000, of which 60% is non-conformance","$180,000, of which 50% is non-conformance"], answer: 1, exp: "Conformance = 30,000 + 50,000 = $80,000 and non-conformance = 70,000 + 50,000 = $120,000, so CoQ = $200,000 and failure work is 120,000/200,000 = 60%. The 40% figure is the conformance share, and $120,000 is only the non-conformance half." },
  { ch: 5, type: "math", q: "The same project moves $20,000 of reactive work into prevention, and every dollar spent preventing defects removes $1.75 of failure cost while appraisal stays at $50,000. What is the new cost of quality?", opts: ["$200,000, unchanged","$204,000, a $4,000 increase","$185,000, a $15,000 reduction","$165,000, a $35,000 reduction"], answer: 2, exp: "Prevention becomes 30,000 + 20,000 = $50,000 and non-conformance falls to 120,000 − (20,000 × 1.75) = $85,000, so CoQ = (50,000 + 50,000) + 85,000 = $185,000 — a $15,000 reduction achieved by spending more on prevention. $204,000 is what happens if prevention only removes $0.80 per dollar, and $35,000 is the failure-cost saving rather than the change in the total." },
  { ch: 5, type: "math", q: "A project has BAC $120,000. At the halfway point EV is $50,000 and AC is $62,000. What cost efficiency must the remaining work achieve to finish on budget?", opts: ["A TCPI of about 0.81","A TCPI of exactly 1.00","A TCPI of about 2.07","A TCPI of about 1.21"], answer: 3, exp: "TCPI = (BAC − EV)/(BAC − AC) = (120,000 − 50,000)/(120,000 − 62,000) = 70,000/58,000 ≈ 1.21, so each remaining dollar must deliver about $1.21 of value. The 0.81 figure is the CPI so far (50,000/62,000), and 1.00 would mean the remaining work merely has to go to plan." },
  { ch: 5, type: "math", q: "A quality-critical release runs A (2 days), then B (6) and C (5) in parallel, then D (4) which needs both, then E (4), F (3) and G (2). What is the project duration, and how much float does C have?", opts: ["21 days, and C has 1 day of float","19 days, and C is on the critical path","21 days, and C has 5 days of float","17 days, and C has 1 day of float"], answer: 0, exp: "The critical path is A → B → D → E → F → G = 2 + 6 + 4 + 4 + 3 + 2 = 21 days; the branch through C totals 2 + 5 + 4 + 4 + 3 + 2 = 20 days, so C carries 21 − 20 = 1 day. C is the only activity with float in this network." },
  { ch: 5, type: "math", q: "A project has BAC $200,000 over eight months. At the end of month 4 it is 40% complete against a plan of 50%, and $110,000 has been spent. What are the CPI and the EAC if the current CPI persists?", opts: ["CPI ≈ 0.73 and EAC = $230,000","CPI ≈ 0.73 and EAC ≈ $275,000","CPI = 0.80 and EAC = $250,000","CPI ≈ 1.38 and EAC ≈ $145,000"], answer: 1, exp: "PV = 0.50 × 200,000 = $100,000 and EV = 0.40 × 200,000 = $80,000, so CPI = 80,000/110,000 = 0.727 ≈ 0.73 and EAC = BAC/CPI = 200,000/0.727 ≈ $275,000. The $230,000 figure is AC + (BAC − EV), which assumes the deviation was a one-off, and 0.80 is the SPI." },

  /* Ch6 */
  { ch: 6, type: "study", q: "A RACI row for go-live approval shows two people in the A column. What is wrong with the matrix?", opts: ["Nothing: accountability is always shared between the sponsor and the project manager","It is wrong because A should contain the people who do the work","Accountability must sit with exactly one person, because shared accountability means no accountability","It is wrong because A cannot appear on an approval task at all"], answer: 2, exp: "A is the single person ultimately answerable for the task; two A's on one row is a matrix defect (two A's in one column are normal). R is the person or people who do the work, C is consulted before the decision and I is informed after it." },
  { ch: 6, type: "study", q: "A team is paid above the market rate, has strong job security and a well-liked manager, but its work is described as boring ticket-shuffling. Which reading fits Herzberg?", opts: ["Both hygiene and motivators are satisfied, so the team should be highly motivated","The hygiene factors are missing, which is why the team is dissatisfied","Herzberg predicts the team will be dissatisfied because pay is the strongest motivator","The hygiene factors are satisfied, so dissatisfaction is low, but the motivators are missing so motivation is lacking"], answer: 3, exp: "Salary, security, conditions and supervision quality are hygiene factors: their absence causes dissatisfaction, but their presence only buys neutrality. Motivation has to come from the work itself through motivators such as achievement, recognition, responsibility and growth." },
  { ch: 6, type: "study", q: "A newly formed distributed team is polite, waits for instructions and has no agreed code-review process. Which stage of Tuckman is this, and what should the project manager do?", opts: ["Forming: clarify purpose, roles and reporting structure, and expect storming next","Storming: mediate the conflict over architecture before it hardens","Norming: hand over decisions and make the emerging norms explicit","Performing: remove blockers and represent the team outwards"], answer: 0, exp: "Forming is polite, dependent and unclear about roles, so the intervention is to clarify purpose, roles and reporting structure. Storming is where positions harden, norming is where working agreements emerge, and performing is high autonomy with shared accountability." },
  { ch: 6, type: "study", q: "A senior developer and the security officer disagree about which encryption library to use, and the release decision is due tomorrow. Which conflict mode is most appropriate?", opts: ["Avoiding: postponing the decision until emotions settle","Compromising: moderate assertiveness and cooperativeness, for a time-constrained decision, with the residual risk recorded","Competing: the senior developer decides alone because the release is due","Accommodating: the security officer gives way to preserve the relationship"], answer: 1, exp: "Compromising is the middle ground for time-constrained situations or temporary solutions, and it produces a partial win-win that must be recorded as residual risk. Avoiding is for minor issues or high emotion, competing is for critical quick decisions at others' expense, and accommodating is for preserving a relationship or where the issue matters more to the other party." },
  { ch: 6, type: "study", q: "A one-week peak needs three testers from a team of two, and the affected activity has four weeks of float. What is the most defensible first response?", opts: ["Recruit an extra tester, because capacity must match the peak","Pay overtime for the peak week, because float should be preserved","Delay the activity within its float, because the peak is movable and delaying costs nothing but float","Accept the over-allocation, because the average utilisation over the month is under 100%"], answer: 2, exp: "Levelling should spend float before money: delaying a floating activity within delta <= F removes the peak at no direct cost. Recruiting answers a permanent capacity shortage rather than a one-week movable peak, overtime is the expensive technique when free float existed, and a comfortable average never proves feasibility because the peak is what breaks the plan." },
  { ch: 6, type: "math", q: "A pool of 4 engineers must cover activity X, which needs 3 engineers in weeks 3–5, and activity Y, which needs 2 engineers in weeks 4–6. What is the peak utilisation, and what does it mean?", opts: ["U_max = 0.83, which is acceptable because the average is below capacity","U_max = 5, so five engineers must be hired","U_max = 1.00, because the two activities never fully overlap","U_max = 1.25 in the overlap weeks, so the plan is infeasible as written"], answer: 3, exp: "In weeks 4 and 5 demand is 3 + 2 = 5 against a capacity of 4, so U = 5/4 = 1.25 and the resource is over-allocated. The 0.83 figure averages demand over the whole window, and 5 is the demand in the peak weeks rather than the number of people to hire." },
  { ch: 6, type: "math", q: "A QA pool has 2 testers. With every activity at its earliest start, demand over weeks 6–10 is 2, 4, 3, 0, 0, so U_max is 2.00. The regression suite has 2 weeks of float and is delayed by 2 weeks. What is the new peak, and what is the cost?", opts: ["U_max falls to 1.00 with the finish date unchanged, but the suite is left with zero float","U_max falls to 0.90, which is the average utilisation","U_max stays at 2.00 because the same tester-weeks are still delivered","U_max rises, because the delayed work collides with the UAT support week"], answer: 0, exp: "Delaying the suite by delta = 2, the largest delta permitted by its float, gives demand 2, 2, 1, 2, 2 and U_max = 1.00 while the same 9 tester-weeks are delivered and the 14-week finish is protected. The price is that the suite now sits on its late finish with no float, and 0.90 is only the average utilisation, which never proves feasibility." },
  { ch: 6, type: "math", q: "A task has ES = 6 and duration 2, and all of its successors start in week 10. It is delayed by 3 weeks. What happens?", opts: ["Nothing: the float absorbs the delay","The two weeks of float are consumed and the finish date slips by one week","The project slips by three weeks immediately","The task becomes critical and its float rises to 4 weeks"], answer: 1, exp: "LF is 10, so LS = 10 − 2 = 8 and the float is 8 − 6 = 2 weeks. A three-week delay consumes both weeks of float and pushes one week into the successors, so the finish slips by one week. Float is not spare capacity: it is exactly the amount the activity can slip before it starts constraining something else." },
  { ch: 6, type: "math", q: "At the end of week 6 of a 12-week, $100,000 project, PV is $52,000, EV is $44,000 and AC is $58,000. What is the TCPI, and what does it mean?", opts: ["0.76: the project's current cost efficiency","0.85: the project's current schedule efficiency","1.33: every remaining dollar must deliver $1.33 of value against a historic rate of $0.76","1.18: the ratio of planned value to earned value"], answer: 2, exp: "TCPI = (BAC − EV)/(BAC − AC) = 56,000/42,000 = 1.33, so the remaining work must be about a third more cost-efficient than the plan assumed. The 0.76 is the CPI so far, 0.85 is the SPI, and 1.18 is PV/EV, which is the reciprocal of SPI." },
  { ch: 6, type: "math", q: "At week 6 the resource lines show: labour planned $36,000 against actual $34,000, cloud capacity planned $10,000 against actual $18,000, and licences $6,000 against $6,000. Which line should be attacked first, and why?", opts: ["Labour, because an underspend is always good news to bank","Licences, because a fixed cost that has not moved is a risk","None: the net +$6,000 over the whole project is too small to act on","Cloud capacity, because its +$8,000 is a resource still being consumed above plan and will keep overrunning"], answer: 3, exp: "Decomposing actual cost by resource line shows that a cheap labour variance is hiding an expensive cloud variance: the labour saving is the shadow of an availability loss, while cloud capacity is consuming above plan and has no reason to stop. A single net variance hides both the cause and the trend." },

  /* Ch7 */
  { ch: 7, type: "study", q: "A defect has been found in the production system and the team is now fixing it. How should this be described in risk terms?", opts: ["It is an issue, not a risk: a risk is an uncertain event that may or may not happen, and this one already has","It is still a risk, because further defects may exist","It is a risk that has been accepted","It is a trigger, because a defect is observable evidence"], answer: 0, exp: "The load-bearing word in the definition of risk is uncertain. Once the event has occurred it is a realised problem to be managed as an issue, and the correct risk move is to close or re-rate the register entry that predicted it and check whether the response worked." },
  { ch: 7, type: "study", q: "A corporate-wide cybersecurity vulnerability can only be patched by the enterprise security team, well outside the project's scope. Which response strategy applies?", opts: ["Transfer, because another party will fix it","Escalation, because the risk sits outside the project's scope and belongs to program or portfolio management","Acceptance, because the project cannot do anything about it","Mitigation, because the project can reduce the probability of exposure"], answer: 1, exp: "Escalation hands a risk up when the project is not the right level to respond. Transfer keeps the risk inside the project and moves only the consequence to a third party through insurance or a vendor SLA, acceptance is only defensible for low exposure, and the project cannot mitigate a vulnerability it does not control." },
  { ch: 7, type: "study", q: "A risk is rated low probability but very high impact, and the register still marks it HIGH priority. What does this demonstrate?", opts: ["That low-probability risks can safely be ignored","That impact alone decides priority in a probability-impact matrix","That the L × S score forces both axes into the decision, where sorting by probability alone would bury the risk","That the rating scale is wrong and should be recalibrated"], answer: 2, exp: "The product of likelihood and severity is what surfaces a severe, unlikely risk. A register sorted by probability would bury it, which is exactly why the licence project rates its privacy and security risk HIGH on a low probability and a very high impact." },
  { ch: 7, type: "study", q: "The project outsources integration work to a vendor with SLA guarantees. What has happened to the risk?", opts: ["The risk has been removed from the project entirely","The risk has been escalated to portfolio management","The risk has been accepted because no action was taken","The consequence has been transferred to a third party, but the project still owns integration quality and carries residual risk"], answer: 3, exp: "Transfer shifts responsibility for the consequence to a third party through insurance, an SLA or outsourcing; the risk itself stays in the project, the project still owns integration quality, and a residual risk remains. Removing risk entirely is avoidance, not transfer." },
  { ch: 7, type: "study", q: "Which of these is a usable risk-register entry?", opts: ["Record integration errors; category Technology; trigger: failed transaction or data mismatch; owner: Integration lead","Integration might go wrong; owner: the team; response: be careful","Technical risk; owner: IT; response: monitor the situation","Record integration errors; owner: the project; trigger: when it happens; response: mitigate"], answer: 0, exp: "A register entry is usable only when it names the event, a category, an observable trigger and a single named owner. Owners must be individuals rather than teams, and a response of be careful is a wish rather than a plan with a strategy and an action." },
  { ch: 7, type: "math", q: "A risk is rated 4 for likelihood and 4 for severity on a 1–5 scale. What is its risk score and its band?", opts: ["8, which is in the MODERATE band","16, which is in the EXTREME band","16, which is in the HIGH band","4, which is in the LOW band"], answer: 1, exp: "r = L × S = 4 × 4 = 16, and the page bands the score as extreme at r ≥ 15, high at 10 ≤ r < 15, moderate at 5 ≤ r < 10 and low below that. Adding the ratings or treating the score as a single rating are the two common errors." },
  { ch: 7, type: "math", q: "A register holds three threats — 0.30 × A$800k, 0.25 × A$500k and 0.15 × A$1.2m — and one opportunity, 0.40 × A$300k. What is the net expected exposure?", opts: ["A$545,000","A$665,000","A$425,000","A$305,000"], answer: 2, exp: "Threat exposure = 240,000 + 125,000 + 180,000 = A$545,000 and opportunity benefit = 0.40 × 300,000 = A$120,000, so E_net = 545,000 − 120,000 = A$425,000. Adding the opportunity gives the A$665,000 error, and A$545,000 is the threat exposure before netting." },
  { ch: 7, type: "math", q: "A project must deliver an integration component. Building in-house costs A$400k with a 70% chance of success and a 30% chance of A$600k of rework. Outsourcing costs A$600k with a 90% chance of success and a 10% chance of A$200k of remediation. Which option has the better expected monetary value?", opts: ["Outsourcing, at −A$620,000 against −A$580,000","In-house, at −A$400,000 against −A$600,000","The two options are equal at −A$600,000","In-house, at −A$580,000 against −A$620,000"], answer: 3, exp: "EMV(in-house) = 0.70 × (−400,000) + 0.30 × (−1,000,000) = −280,000 − 300,000 = −A$580,000. EMV(outsource) = 0.90 × (−600,000) + 0.10 × (−800,000) = −540,000 − 80,000 = −A$620,000. In-house wins by A$40,000 of expected value, but its worst case is A$1.0m against A$0.8m, which is why a risk-averse organisation may still buy the outsourcing." },
  { ch: 7, type: "math", q: "Simulation gives a mean completion cost of A$2.1m with a standard deviation of A$150k, and the organisation commits at 90% confidence. What is the commitment figure and the reserve against a A$2.0m baseline?", opts: ["A$2,292,000, a reserve of A$292,000","A$2,292,000, a reserve of A$192,000","A$2,100,000, a reserve of A$100,000","A$2,347,500, a reserve of A$347,500"], answer: 0, exp: "The 90% confidence factor is z = 1.28, so D90 = 2,100,000 + 1.28 × 150,000 = A$2,292,000, and CR90 = 2,292,000 − 2,000,000 = A$292,000. A$192,000 is the reserve against the mean rather than the baseline, and A$100,000 is only the expected drift from baseline to mean." },
  { ch: 7, type: "math", q: "The critical activities of a network have variances summing to 2.82, giving a standard deviation of 1.68 days around a 23-day deterministic finish. What is the 90% confidence date?", opts: ["About 26.8 days","About 25.2 days","About 23 days","About 26.4 days"], answer: 1, exp: "23 + 1.28 × 1.68 = 25.15 ≈ 25.2 days, roughly two to three days of schedule reserve on the critical chain. Standard deviations are not added — variances are — and only the critical activities are summed, because activities with float do not drive the finish date." },

  /* Ch8 */
  { ch: 8, type: "study", q: "A project must engage a vendor for work whose requirements are still being discovered, and the buyer wants the vendor to have a real incentive to keep costs down. Which contract family fits best?", opts: ["Firm fixed price, because it caps the buyer's cost","Time and materials, because the scope keeps changing","Cost plus incentive fee, because costs are reimbursed but the fee varies with measured performance","Cost plus award fee, because the buyer decides what the work was worth"], answer: 2, exp: "CPIF reimburses actual cost and restores the cost-control pressure a plain CPFF removes. FFP on undiscovered scope makes the seller either price in a large risk premium or cut corners, T&M carries no explicit cost-control incentive, and CPAF is the most subjective of the six because the award depends on buyer satisfaction." },
  { ch: 8, type: "study", q: "Which statement about where cost risk sits is correct?", opts: ["A fixed-price contract removes cost risk from the project altogether","Cost-reimbursable contracts put cost risk on the seller because the fee is fixed","Time and materials contracts put all cost risk on the seller because rates are agreed","A fixed-price contract puts cost risk on the seller, a cost-reimbursable contract puts it on the buyer, and T&M splits it between them"], answer: 3, exp: "Fixed-price is low buyer risk and high seller risk, cost-reimbursable is high buyer risk and low seller risk, and T&M is medium on both sides. A fixed price transfers risk rather than removing it: the seller prices the risk in, resists changes and may cut corners to protect margin." },
  { ch: 8, type: "study", q: "A university must buy 400 identical laptops with fixed specifications before semester starts. Which document is appropriate?", opts: ["An RFQ, because the items are standardised and the decision turns on price and delivery","An RFP, because vendors should propose how they would meet the requirement","A make-or-buy analysis, because the laptops might be built in house","A weighted scoring model with capability weighted most heavily"], answer: 0, exp: "An RFQ solicits price quotations for well-defined, standardised goods and is evaluated mainly on cost and delivery. An RFP asks vendors how they would solve a problem and is evaluated on quality, approach and capability as well as price, which is slow and expensive when the requirement is already standard." },
  { ch: 8, type: "study", q: "A supplier has been delivering for two years. The project manager now wants monthly reporting on on-time delivery and defect rate. Which tool is this?", opts: ["A checklist, which screens vendors against minimum standards before award","A vendor scorecard, which is retrospective, continuous KPI monitoring after award","A weighted scoring model, which compares competing proposals on weighted criteria","An RFQ, which obtains comparable price quotations"], answer: 1, exp: "The scorecard is a post-award monitoring instrument for long-term supplier relationships, reporting KPIs such as delivery timeliness, quality, cost and compliance as scores or traffic lights. Weighted scoring and checklists are pre-award selection tools, and treating the scorecard as a selection tool is the listed common error." },
  { ch: 8, type: "study", q: "A vendor has the highest weighted score but fails a mandatory security certification. What should happen?", opts: ["The vendor wins, because the weighted model is the published evaluation method","The vendor is kept but a penalty clause is added to the contract","The vendor is excluded: compliance is a gate, and a weighted score cannot rescue a bid that fails a mandatory requirement","The security criterion is reweighted to zero so the scores stay comparable"], answer: 2, exp: "Mandatory gates are checked before scores decide anything: the weighted model ranks only the vendors that pass them. Adding penalties or reweighting the criteria would change the published basis of evaluation after the fact and would not make an uncertified vendor compliant." },
  { ch: 8, type: "math", q: "Building a regression-testing capability costs $180,000 in tooling plus $40 per test run; a vendor charges $100 per run. Forecast demand is 2,000 runs. Which option is cheaper, and by how much?", opts: ["Building, by $60,000, because the fixed cost is spread over 2,000 runs","The two options cost the same once the fixed cost is amortised","Buying, by $20,000, because the vendor price is $60 lower per run","Buying, by $60,000, because 2,000 runs is below the 3,000-run break-even"], answer: 3, exp: "Q* = F/(p − v) = 180,000/(100 − 40) = 3,000 runs. At 2,000 runs, building costs 180,000 + 40 × 2,000 = $260,000 against buying at 100 × 2,000 = $200,000, so buying is cheaper by $60,000. The two options are equal only at the break-even volume." },
  { ch: 8, type: "math", q: "Vendors A and B score 9, 9, 7, 5 and 7, 6, 9, 9 on capability, security, delivery and price. With weights of 0.35, 0.30, 0.25 and 0.10, who wins and by how much?", opts: ["Vendor A, by 0.70 (8.10 against 7.40)","Vendor A, by 1.10 (7.60 against 6.50)","Vendor B, because it leads on delivery and price","The vendors tie, because their strengths offset"], answer: 0, exp: "A = 0.35(9) + 0.30(9) + 0.25(7) + 0.10(5) = 3.15 + 2.70 + 1.75 + 0.50 = 8.10 and B = 2.45 + 1.80 + 2.25 + 0.90 = 7.40, a gap of 0.70. The 7.60/6.50 pair leaves the price criterion out of the model, and leading on two criteria does not win when capability and security carry 65% of the weight — which is why the criteria and weights are published in the RFP before any proposal is opened." },
  { ch: 8, type: "math", q: "Vendor X quotes $120k acquisition, $75k of running cost over three years and $15k to exit. Vendor Y quotes $80k acquisition, $135k running and $40k exit. Which has the lower total cost of ownership, and by how much?", opts: ["Vendor Y, by $45,000","Vendor X, by $45,000","Vendor Y, because its acquisition cost is $40,000 lower","They are equal once running costs are included"], answer: 1, exp: "TCO(X) = 120 + 75 + 15 = $210k and TCO(Y) = 80 + 135 + 40 = $255k, so the lower bid loses on ownership cost by $45,000. A cheaper licence with a higher support annuity and a punitive exit is frequently the more expensive purchase." },
  { ch: 8, type: "math", q: "An incentive contract has target cost $500,000, target fee $50,000, a seller's share of 30% and a ceiling of $580,000. Actual cost comes in at $520,000. What is the final fee and the price?", opts: ["$50,000 and $570,000","$44,000 and $520,000","$44,000 and $564,000","$56,000 and $576,000"], answer: 2, exp: "fee = f_t + α_s(C_t − C_a) = 50,000 + 0.30(500,000 − 520,000) = 50,000 − 6,000 = $44,000, and price = C_a + fee = 520,000 + 44,000 = $564,000. The buyer pays $14,000 more than the $550,000 target while the seller's fee falls by $6,000 — the 70/30 split in action." },
  { ch: 8, type: "math", q: "In the TechSolutions procurement schedule, hardware procurement (P1) has duration 4 weeks, follows contract award (C, which finishes at week 5), and must complete before testing and acceptance starts at week 16. How much float does P1 have?", opts: ["0 weeks","11 weeks","5 weeks","7 weeks"], answer: 3, exp: "P1 runs from week 5 to week 9, and its late finish is the late start of testing and acceptance, which is week 16 with zero float, so LS = 16 − 4 = 12 and the float is 12 − 5 = 7 weeks. Only the deployment chain is critical: the parallel procurement branches can slip by five to eight weeks without moving the finish." },
];
